-- ============================================================
-- CERVICED — import Gina's Maintenance Directory as claimable listings
-- Run in Supabase SQL Editor AFTER the private_provider_claim_codes migration.
--
-- Inserts 521 unclaimed (is_claimed = false, source = 'scraped') providers.
-- Skips 7 Instagram profiles that no longer exist.
-- Idempotent: re-running skips rows whose slug or source_url already exists.
--
-- display_name = Instagram handle (the directory has no business names);
-- website     = booking link from the Instagram bio (when they have one);
-- email       = NULL — the owner adds their own account email when claiming.
-- booking_mode = external — these are directory/link-only listings, not
--                CERVICED-bookable providers. Use the bio link where present,
--                otherwise their public source page until the owner updates it.
-- ============================================================
INSERT INTO public.providers
  (slug, display_name, service_category, custom_service_type, location_text,
   instagram, website, external_booking_url, booking_mode, source_url, source, source_site, is_active, is_claimed,
   scraped_at, scraped_fields)
SELECT v.slug, v.display_name, v.service_category, v.custom_service_type, v.location_text,
       v.instagram, v.website, COALESCE(v.website, v.source_url), 'external', v.source_url,
       'scraped', 'ginasmaintenancedirectory', TRUE, FALSE,
       NOW(),
       ARRAY['display_name','location_text','instagram'] || CASE WHEN v.website IS NULL THEN '{}'::text[] ELSE ARRAY['website'] END
FROM (VALUES
